import React from 'react';
import { Link } from 'react-router-dom';
import './Navbar.css';

function Navbar({ user, onLogout, cartCount }) {
  return (
    <nav className="navbar">
      <div className="navbar-container">
        <Link to="/" className="navbar-logo">
          🎮 ROBLOX SHOP VIỆT
        </Link>
        <ul className="navbar-menu">
          <li><Link to="/">Trang Chủ</Link></li>
          <li><Link to="/history">Lịch Sử Mua Nick</Link></li>
          <li><Link to="/services">Dịch Vụ Khác</Link></li>
          <li><Link to="/recharge">Nạp Tiền</Link></li>
          <li><Link to="/wallet">Dùng Tiền</Link></li>
          <li><Link to="/news">Tin Tức</Link></li>
          <li><Link to="/cart">Giỏ Hàng ({cartCount})</Link></li>
          {user ? (
            <>
              <li className="user-info">👤 {user.username}</li>
              <li><button onClick={onLogout} className="logout-btn">Đăng Xuất</button></li>
            </>
          ) : (
            <>
              <li><Link to="/login">Đăng Nhập</Link></li>
              <li><Link to="/register">Đăng Ký</Link></li>
            </>
          )}
        </ul>
      </div>
    </nav>
  );
}

export default Navbar;
